import { useLayoutEffect, useState } from "react";
import DashboardLayout from "@/components/layouts/DashboardLayout";
import {
  useListingStore,
  useSelectListingStore,
} from "@/permissionless-listing/store/useListingStore";
import ListingBody from "@/permissionless-listing/sections/body";
import { useTranslation } from "@/i18n";
import { PageView } from "@/permissionless-listing/types";

export default function PermissionlessListingPage() {
  const { t } = useTranslation();
  const [ready, setReady] = useState(
    () => useListingStore.getState().currentPage === PageView.Dashboard
  );
  const { setPage } = useSelectListingStore(s => ({
    setPage: s.setPage,
  }));

  useLayoutEffect(() => {
    setPage(PageView.Dashboard);
    setReady(true);
  }, [setPage]);

  return (
    <DashboardLayout title={t("navigation.permissionlessListing")}>
      {ready ? <ListingBody /> : null}
    </DashboardLayout>
  );
}
